INSERT INTO "Faq" ("id", "question", "answer", "serviceType", "keywords", "displayOrder", "active", "published", "updatedAt")
VALUES
  ('faq-flight-special-fare-1', 'What is a Special Fare?', 'A Special Fare is a request-based flight service where TripNexio checks offline airline, agency and partner sources to find available fares for your route and travel date.', 'FLIGHT_SPECIAL_FARE', ARRAY['special', 'fare', 'request-based', 'flight']::text[], 1, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-2', 'What makes a Special Fare different?', 'TripNexio may have access to group or pre-purchased airline/agency inventory for selected routes and dates. When available, this inventory can be offered at a discounted special fare. If special inventory is unavailable, regular offline fares can also be checked.', 'FLIGHT_SPECIAL_FARE', ARRAY['makes', 'special', 'fare', 'different']::text[], 2, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-3', 'Are Special Fares always the cheapest in the market?', 'Not necessarily. Special fares can be strongly discounted when special inventory is available, but the final fare depends on route, travel date, airline, passenger type and current inventory.', 'FLIGHT_SPECIAL_FARE', ARRAY['special', 'fares', 'always', 'cheapest']::text[], 3, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-4', 'Is Special Fare a live flight search?', 'No. Special Fare is an offline, request-based service. There is no public live flight search or public live airline inventory.', 'FLIGHT_SPECIAL_FARE', ARRAY['special', 'fare', 'live', 'flight']::text[], 4, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-5', 'Do you offer domestic flights in India?', 'Yes. TripNexio plans to support major domestic cities and routes in India through its configured airport, airline and partner network.', 'FLIGHT_SPECIAL_FARE', ARRAY['offer', 'domestic', 'flights', 'india']::text[], 5, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-6', 'Do you offer international flights?', 'Yes. TripNexio can provide Special Fare options for supported destinations worldwide, subject to the configured network and availability.', 'FLIGHT_SPECIAL_FARE', ARRAY['offer', 'international', 'flights', 'tripnexio']::text[], 6, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-7', 'Can I request a normal fare if a Special Fare is unavailable?', 'Yes. TripNexio can also check regular offline fares through its airline, agency and partner relationships.', 'FLIGHT_SPECIAL_FARE', ARRAY['normal', 'fare', 'special', 'unavailable']::text[], 7, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-8', 'What information do I need to request a fare?', 'You need your full name, mobile number, email address, departure city/airport, destination city/airport, travel date and passenger details.', 'FLIGHT_SPECIAL_FARE', ARRAY['information', 'fare', 'full', 'name']::text[], 8, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-9', 'How far in advance can I request a Special Fare?', 'The current request window is up to 45 days before travel.', 'FLIGHT_SPECIAL_FARE', ARRAY['far', 'advance', 'special', 'fare']::text[], 9, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-10', 'Can I book for multiple passengers?', 'Yes. Special Fare supports multiple passengers.', 'FLIGHT_SPECIAL_FARE', ARRAY['book', 'multiple', 'passengers', 'special']::text[], 10, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-11', 'How are Adult, Child and Infant fares determined?', 'Passenger type is calculated from the traveller''s date of birth and age on the travel date: Adult 12+, Child 2–11, Infant under 2.', 'FLIGHT_SPECIAL_FARE', ARRAY['adult', 'child', 'infant', 'fares']::text[], 11, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-12', 'Can I use an existing passenger profile?', 'Yes. Existing passenger data can be reused, including valid passport information where applicable.', 'FLIGHT_SPECIAL_FARE', ARRAY['use', 'existing', 'passenger', 'profile']::text[], 12, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-13', 'Will I receive multiple flight options?', 'You may receive multiple options when available. Options can differ by airline, timing, route or fare.', 'FLIGHT_SPECIAL_FARE', ARRAY['receive', 'multiple', 'flight', 'options']::text[], 13, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-14', 'How long is my Special Fare quotation valid?', 'A Special Fare quotation can be valid for a maximum of 30 minutes. The exact expiry is shown on the quotation.', 'FLIGHT_SPECIAL_FARE', ARRAY['long', 'special', 'fare', 'quotation']::text[], 14, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-15', 'What happens if my quote expires?', 'Payment is blocked and you need to request a new quote. The expired quote cannot simply be reused.', 'FLIGHT_SPECIAL_FARE', ARRAY['happens', 'quote', 'expires', 'payment']::text[], 15, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-16', 'Can I request another route if my preferred route is unavailable?', 'Yes. TripNexio may offer an alternative route, which must be clearly identified as an alternative.', 'FLIGHT_SPECIAL_FARE', ARRAY['another', 'route', 'preferred', 'unavailable']::text[], 16, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-17', 'Does payment mean my ticket is confirmed?', 'No. Final seat and fare availability is reconfirmed after payment by the TripNexio team/partner.', 'FLIGHT_SPECIAL_FARE', ARRAY['payment', 'mean', 'ticket', 'confirmed']::text[], 17, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-18', 'What happens if my selected fare becomes unavailable after payment?', 'TripNexio may offer an alternative. If the alternative costs more, you can pay the difference or request a refund. If it costs less, the applicable difference can be refunded. If no suitable alternative is available, a full refund is processed.', 'FLIGHT_SPECIAL_FARE', ARRAY['happens', 'selected', 'fare', 'becomes']::text[], 18, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-19', 'Do I have to accept a higher-fare alternative?', 'No. You can pay the additional amount or request a refund. You are not forced to accept a higher fare.', 'FLIGHT_SPECIAL_FARE', ARRAY['accept', 'higher-fare', 'alternative', 'pay']::text[], 19, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-20', 'Is baggage included?', 'Baggage information is shown with the quoted flight option and is based on the applicable airline/fare details.', 'FLIGHT_SPECIAL_FARE', ARRAY['baggage', 'included', 'information', 'shown']::text[], 20, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-21', 'Can I cancel my Special Fare booking?', 'Cancellation may be requested subject to the applicable airline/partner fare rules and configured cancellation charges.', 'FLIGHT_SPECIAL_FARE', ARRAY['cancel', 'special', 'fare', 'booking']::text[], 21, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-22', 'How is a refund calculated?', 'The configured refund calculation is Paid Amount minus applicable Partner/Airline Cancellation Charge minus Gateway Charge.', 'FLIGHT_SPECIAL_FARE', ARRAY['refund', 'calculated', 'configured', 'calculation']::text[], 22, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-23', 'When will I receive my ticket?', 'After final availability is confirmed and the ticket is issued, the ticket is delivered through the configured customer channels.', 'FLIGHT_SPECIAL_FARE', ARRAY['receive', 'ticket', 'final', 'availability']::text[], 23, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-24', 'Can I request a Special Fare through WhatsApp?', 'Yes. The service supports website, WhatsApp, CRM and other configured sources.', 'FLIGHT_SPECIAL_FARE', ARRAY['special', 'fare', 'through', 'whatsapp']::text[], 24, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-25', 'Will TripNexio follow up if I do not book?', 'The configured workflow can follow up every 7 days until you book, stop the follow-up or opt out.', 'FLIGHT_SPECIAL_FARE', ARRAY['tripnexio', 'follow', 'book', 'configured']::text[], 25, true, true, CURRENT_TIMESTAMP),
  ('faq-flight-special-fare-26', 'Are Return Ticket and OTB included in Special Fare?', 'No. Return Ticket and OTB are separate services. They may be offered as later upsells where relevant.', 'FLIGHT_SPECIAL_FARE', ARRAY['return', 'ticket', 'otb', 'included']::text[], 26, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-1', 'What is a Return Verified Ticket?', 'It is a return ticket arranged for international travel and intended to provide proof of return travel where applicable.', 'RETURN_TICKET', ARRAY['return', 'verified', 'ticket', 'arranged']::text[], 1, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-2', 'Why might I need a return or return ticket?', 'Some airlines, immigration authorities, visa processes or travel situations may require proof of return or return travel.', 'RETURN_TICKET', ARRAY['why', 'might', 'return', 'ticket']::text[], 2, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-3', 'Is this service for international travel?', 'Yes. TripNexio''s Return Verified Ticket service is positioned for international travel, subject to supported destinations and configured airline/partner availability.', 'RETURN_TICKET', ARRAY['service', 'international', 'travel', 'tripnexio']::text[], 3, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-4', 'Which destinations are supported?', 'Destination availability is controlled by TripNexio''s configured service and partner/airline availability. Only supported destinations and options should be shown to the customer.', 'RETURN_TICKET', ARRAY['destinations', 'supported', 'destination', 'availability']::text[], 4, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-5', 'What information do I need to provide?', 'You will need your full name, mobile number, email address, destination country, number of passengers and travel date.', 'RETURN_TICKET', ARRAY['information', 'full', 'name', 'mobile']::text[], 5, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-6', 'Do I need to select a visa or travel duration?', 'No. The customer is not asked to select a visa or travel duration for this service.', 'RETURN_TICKET', ARRAY['select', 'visa', 'travel', 'duration']::text[], 6, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-7', 'Do I need to provide my visa validity?', 'No. The customer is not asked to provide a visa-validity date.', 'RETURN_TICKET', ARRAY['visa', 'validity', 'customer', 'asked']::text[], 7, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-8', 'Can I choose an expected return date?', 'Yes. You provide an expected return date. TripNexio aims to issue a suitable return ticket on or near that date, subject to live ticket availability.', 'RETURN_TICKET', ARRAY['choose', 'expected', 'return', 'date']::text[], 8, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-9', 'Will the ticket be issued on the exact date I request?', 'The reservation is issued according to available ticket options and the applicable travel schedule. An exact issue date is not selected by the customer.', 'RETURN_TICKET', ARRAY['ticket', 'issued', 'exact', 'date']::text[], 9, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-10', 'What documents are required?', 'A passport copy is required. Existing return ticket information may be provided where applicable. A visa copy is optional where applicable.', 'RETURN_TICKET', ARRAY['documents', 'passport', 'copy', 'existing']::text[], 10, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-11', 'Is the ticket actually verifiable?', 'Where supported by the selected airline/partner, the issued reservation can be checked on the airline website using the PNR and the basic reservation information.', 'RETURN_TICKET', ARRAY['ticket', 'actually', 'verifiable', 'supported']::text[], 11, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-12', 'What is a PNR?', 'A PNR is the reservation reference associated with the ticket or booking. It is used together with basic passenger/reservation information to retrieve the reservation where the airline supports online verification.', 'RETURN_TICKET', ARRAY['pnr', 'reservation', 'reference', 'associated']::text[], 12, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-13', 'Does an issued reservation guarantee boarding?', 'No. A reservation does not guarantee boarding.', 'RETURN_TICKET', ARRAY['issued', 'reservation', 'guarantee', 'boarding']::text[], 13, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-14', 'Does an issued reservation guarantee immigration clearance?', 'No. TripNexio does not control or guarantee immigration or border clearance decisions.', 'RETURN_TICKET', ARRAY['issued', 'reservation', 'guarantee', 'immigration']::text[], 14, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-15', 'Does the ticket guarantee visa approval?', 'No. Visa approval is a separate decision made by the relevant authority.', 'RETURN_TICKET', ARRAY['ticket', 'guarantee', 'visa', 'approval']::text[], 15, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-16', 'When will I receive my ticket?', 'Once the reservation is successfully issued through the configured airline/partner process, TripNexio delivers the ticket through the available customer channels.', 'RETURN_TICKET', ARRAY['receive', 'ticket', 'once', 'reservation']::text[], 16, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-17', 'Can I cancel my Return Verified Ticket?', 'Cancellation may be requested according to the configured refund policy. A cancellation fee may apply.', 'RETURN_TICKET', ARRAY['cancel', 'return', 'verified', 'ticket']::text[], 17, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-18', 'Will I receive a full refund if I cancel?', 'Not necessarily. The eligible refund depends on the configured cancellation policy and the stage of processing. Applicable cancellation charges and non-refundable amounts may be deducted.', 'RETURN_TICKET', ARRAY['receive', 'full', 'refund', 'cancel']::text[], 18, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-19', 'Can I get a refund after my request is forwarded to the airline/partner?', 'No. Once documents are validated and the request is forwarded to the airline/partner, the booking becomes non-refundable under the current business rules.', 'RETURN_TICKET', ARRAY['get', 'refund', 'forwarded', 'airline']::text[], 19, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-20', 'What happens after the ticket is issued?', 'The ticket PDF is uploaded to the TripNexio system and delivered to the customer through the configured channels, such as WhatsApp, email and the customer portal.', 'RETURN_TICKET', ARRAY['happens', 'ticket', 'issued', 'pdf']::text[], 20, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-21', 'What happens after my travel date has passed?', 'The service can be automatically marked completed after the planned travel schedule according to the configured post-travel workflow.', 'RETURN_TICKET', ARRAY['happens', 'travel', 'date', 'passed']::text[], 21, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-22', 'What if the airline changes or cancels my flight?', 'Airline schedule changes, cancellations, delays and other airline decisions are outside TripNexio''s control, subject to applicable law and the agreed Terms & Conditions.', 'RETURN_TICKET', ARRAY['airline', 'changes', 'cancels', 'flight']::text[], 22, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-23', 'Can an existing TripNexio customer reuse information?', 'Yes. Where valid information and documents already exist in the customer record, TripNexio can reuse them and ask only for missing or updated information where applicable.', 'RETURN_TICKET', ARRAY['existing', 'tripnexio', 'customer', 'reuse']::text[], 23, true, true, CURRENT_TIMESTAMP),
  ('faq-return-ticket-24', 'Can I book for multiple passengers?', 'Yes. The service supports multiple passengers, with pricing configured per passenger type where applicable.', 'RETURN_TICKET', ARRAY['book', 'multiple', 'passengers', 'service']::text[], 24, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-1', 'Who can apply for a UAE Visa Extension through TripNexio?', 'TripNexio currently provides Visa Extension for UAE visas originally issued through TripNexio.', 'VISA_EXTENSION', ARRAY['apply', 'uae', 'visa', 'extension']::text[], 1, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-2', 'Can I extend a UAE visa issued by another provider?', 'The current TripNexio Visa Extension service is available only for visas originally issued through TripNexio. If your visa was not issued through TripNexio, we will guide you to Visa Change.', 'VISA_EXTENSION', ARRAY['extend', 'uae', 'visa', 'issued']::text[], 2, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-3', 'What happens if my TripNexio visa cannot be found?', 'If we cannot find an eligible TripNexio-issued visa, we will guide you to Visa Change.', 'VISA_EXTENSION', ARRAY['happens', 'tripnexio', 'visa', 'cannot']::text[], 3, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-4', 'What information do I need to request an extension?', 'You need your name, mobile number, email address, passport number, and current UAE visa expiry date.', 'VISA_EXTENSION', ARRAY['information', 'extension', 'name', 'mobile']::text[], 4, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-5', 'Is the visa expiry date required?', 'Yes. The current UAE visa expiry date is required when submitting a Visa Extension request.', 'VISA_EXTENSION', ARRAY['visa', 'expiry', 'date', 'uae']::text[], 5, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-6', 'Do I need to provide my UAE entry date?', 'No. UAE Entry Date is not required for the customer-facing Visa Extension request.', 'VISA_EXTENSION', ARRAY['uae', 'entry', 'date', 'customer-facing']::text[], 6, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-7', 'Can an existing customer use their previous TripNexio visa record?', 'Yes. Existing customer records can be used to identify the relevant passenger and visa.', 'VISA_EXTENSION', ARRAY['existing', 'customer', 'use', 'their']::text[], 7, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-8', 'How long is the visa extension?', 'The current TripNexio Visa Extension service provides a 30-day extension.', 'VISA_EXTENSION', ARRAY['long', 'visa', 'extension', 'tripnexio']::text[], 8, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-9', 'Can my 30-day or 60-day UAE visa be extended?', 'The original visa type is checked as part of the extension review. Final eligibility is determined after verification of the actual visa and applicable requirements.', 'VISA_EXTENSION', ARRAY['day', 'uae', 'visa', 'extended']::text[], 9, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-10', 'Can I request an extension if my visa has already expired?', 'A visa expired for less than 30 days may proceed to review, subject to applicable requirements and fine/overstay handling. A visa expired for 30 days or more is not eligible for the 30-day Extension.', 'VISA_EXTENSION', ARRAY['extension', 'visa', 'already', 'expired']::text[], 10, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-11', 'What if my visa expires today?', 'Same-day expiry cases require urgent handling. Payment must be completed within the applicable operational deadline, currently 6:00 PM on the same working day.', 'VISA_EXTENSION', ARRAY['visa', 'expires', 'today', 'same-day']::text[], 11, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-12', 'How much does a UAE Visa Extension cost?', 'The final amount is provided after your visa and extension eligibility are reviewed. It may include the extension fee, applicable fine or overstay amount, and other applicable charges.', 'VISA_EXTENSION', ARRAY['much', 'uae', 'visa', 'extension']::text[], 12, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-13', 'Do I have to pay an overstay fine?', 'An applicable fine or overstay amount may be added where required. The amount remains subject to the relevant authority rules.', 'VISA_EXTENSION', ARRAY['pay', 'overstay', 'fine', 'applicable']::text[], 13, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-14', 'How long is the payment link valid?', 'The payment link is valid for 24 hours. If it expires, a new payment link may be generated.', 'VISA_EXTENSION', ARRAY['long', 'payment', 'link', 'valid']::text[], 14, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-15', 'Do I need to upload all my documents again?', 'Not necessarily. Eligible existing documents may be offered for reuse after your confirmation. Additional information or documents may be requested if required.', 'VISA_EXTENSION', ARRAY['upload', 'documents', 'again', 'necessarily']::text[], 15, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-16', 'Can I choose whether to reuse an existing document?', 'Yes. Where eligible, you may choose to use an existing document or upload a new one.', 'VISA_EXTENSION', ARRAY['choose', 'whether', 'reuse', 'existing']::text[], 16, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-17', 'When does the new 30-day extension start?', 'The new 30-day extension validity is counted from the original visa expiry date.', 'VISA_EXTENSION', ARRAY['new', 'day', 'extension', 'start']::text[], 17, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-18', 'How will I receive my extended visa?', 'Once the extension is completed, the extended visa copy is delivered through the available WhatsApp and email communication channels.', 'VISA_EXTENSION', ARRAY['receive', 'extended', 'visa', 'once']::text[], 18, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-19', 'What happens if my extension is Not Accepted?', 'The current rule provides a refund of the payment minus applicable gateway charges for a Not Accepted outcome.', 'VISA_EXTENSION', ARRAY['happens', 'extension', 'accepted', 'rule']::text[], 19, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-20', 'What happens if my extension is Rejected?', 'A formal Rejected outcome currently has no refund under the locked Extension rules.', 'VISA_EXTENSION', ARRAY['happens', 'extension', 'rejected', 'formal']::text[], 20, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-extension-21', 'Will I be reminded before my extended visa expires?', 'Yes. One reminder is scheduled around Day 25 after a successful 30-day extension, subject to the configured reminder rules.', 'VISA_EXTENSION', ARRAY['reminded', 'extended', 'visa', 'expires']::text[], 21, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-1', 'What is a New UAE Visa request?', 'It is an online application for an available UAE visa product. You select the visa option, provide traveller details, complete payment, upload required documents and track the application through TripNexio.', 'NEW_VISA', ARRAY['new', 'uae', 'visa', 'online']::text[], 1, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-2', 'Can I apply for a UAE visa from any Indian state?', 'Yes. From every Indian state to different applicant profiles, TripNexio provides a simple way to apply for your UAE visa online. Applications remain subject to applicable UAE visa requirements and the relevant authority’s decision.', 'NEW_VISA', ARRAY['apply', 'uae', 'visa', 'indian']::text[], 2, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-3', 'Can an ECR passport holder apply for a UAE tourist visa?', 'Yes. An ECR passport holder can apply for a UAE tourist or visit visa. The Ministry of External Affairs states that ECR passport holders travelling to an ECR country for purposes other than employment do not require emigration clearance; for employment travel, applicable emigration-clearance requirements apply.', 'NEW_VISA', ARRAY['ecr', 'passport', 'holder', 'apply']::text[], 3, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-4', 'Do I need to create an account to apply?', 'No. After clicking Apply for UAE Visa, you can choose Login or Continue as Guest.', 'NEW_VISA', ARRAY['create', 'account', 'apply', 'clicking']::text[], 4, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-5', 'Can I use Google to sign in?', 'Yes. Google Sign-In can be offered under the Login option.', 'NEW_VISA', ARRAY['use', 'google', 'sign', 'sign-in']::text[], 5, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-6', 'Can I apply for more than one traveller?', 'Yes. A booking can include multiple passengers, including adults and children.', 'NEW_VISA', ARRAY['apply', 'more', 'than', 'one']::text[], 6, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-7', 'Can I add travellers later?', 'The application UI should allow adding travellers before final submission, and the adult/child quantities and total price should update dynamically.', 'NEW_VISA', ARRAY['add', 'travellers', 'later', 'application']::text[], 7, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-8', 'Can I apply for a child?', 'Yes. Applicants under 18 years must apply with at least one parent in the same booking, and the child must be linked to that parent.', 'NEW_VISA', ARRAY['apply', 'child', 'applicants', 'under']::text[], 8, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-9', 'Which UAE visa options are available?', 'The TripNexio product area can offer 30-day and 60-day stay options with Single Entry or Multiple Entry, subject to the products configured and available at the time of application.', 'NEW_VISA', ARRAY['uae', 'visa', 'options', 'available']::text[], 9, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-10', 'Are Adult and Child prices different?', 'Adult and Child pricing can be configured separately. The payable amount is based on the selected visa product and traveller quantities.', 'NEW_VISA', ARRAY['adult', 'child', 'prices', 'different']::text[], 10, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-11', 'What information do I need to start my application?', 'You generally need the applicant name, mobile number and email address, traveller basic details, occupation/profile information, expected travel date, selected visa option, visa type and processing preference.', 'NEW_VISA', ARRAY['information', 'start', 'application', 'generally']::text[], 11, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-12', 'What documents are normally required?', 'The standard New Visa checklist includes Passport Front Page, Passport Last Page and Passport Photograph. Additional documents may be requested depending on the application, traveller profile or authority requirements.', 'NEW_VISA', ARRAY['documents', 'normally', 'standard', 'new']::text[], 12, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-13', 'When do I upload my passport and documents?', 'After successful payment, your Booking ID is created and the document-upload stage becomes available.', 'NEW_VISA', ARRAY['upload', 'passport', 'documents', 'successful']::text[], 13, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-14', 'What is the difference between Normal and Express processing?', 'Normal currently uses a minimum planned travel timeline of 7 days, while Express uses 3 days, subject to working days, configured service timelines and processing conditions.', 'NEW_VISA', ARRAY['difference', 'between', 'normal', 'express']::text[], 14, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-15', 'Does Express guarantee faster visa approval?', 'No. Express processing does not guarantee visa approval or a fixed authority decision time.', 'NEW_VISA', ARRAY['express', 'guarantee', 'faster', 'visa']::text[], 15, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-16', 'What is the difference between visa validity and stay duration?', 'Visa validity is the period within which you must enter the UAE according to the issued visa. Stay duration is the permitted period you may remain in the UAE according to the issued visa conditions.', 'NEW_VISA', ARRAY['difference', 'between', 'visa', 'validity']::text[], 16, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-17', 'What happens after I make payment?', 'Successful payment creates the Booking ID and starts the confirmed visa workflow, including document upload and application processing.', 'NEW_VISA', ARRAY['happens', 'make', 'payment', 'successful']::text[], 17, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-18', 'Can additional documents be requested later?', 'Yes. Additional information or documents may be requested during processing or authority review.', 'NEW_VISA', ARRAY['additional', 'documents', 'later', 'information']::text[], 18, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-19', 'Can I extend my UAE tourist visa?', 'Yes, eligible UAE tourist or visit visas may be extendable, subject to the visa type, applicable immigration rules, timing, fees and the decision of the relevant authority. Extension is not automatic for every visa.', 'NEW_VISA', ARRAY['extend', 'uae', 'tourist', 'visa']::text[], 19, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-20', 'Can TripNexio help with a UAE visa extension?', 'Yes. TripNexio may assist with eligible UAE visa extension services. Availability and processing depend on the visa category, applicable immigration requirements and approval by the relevant authority.', 'NEW_VISA', ARRAY['tripnexio', 'help', 'uae', 'visa']::text[], 20, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-21', 'What happens if I overstay my UAE visa?', 'Applicable UAE government overstay fines may apply if the permitted stay or other applicable period is exceeded. Any government fine is the passenger’s responsibility and must be settled with the relevant authority.', 'NEW_VISA', ARRAY['happens', 'overstay', 'uae', 'visa']::text[], 21, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-22', 'Can job-seeker or other applicant profiles apply?', 'TripNexio accepts applications from different applicant profiles where the selected visa service is applicable. The application remains subject to the applicable UAE visa requirements and authority decision.', 'NEW_VISA', ARRAY['job-seeker', 'other', 'applicant', 'profiles']::text[], 22, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-23', 'Can I work in the UAE on a tourist visa?', 'No. A tourist visa does not itself authorize employment. Any employment requires the applicable UAE employment and immigration process.', 'NEW_VISA', ARRAY['work', 'uae', 'tourist', 'visa']::text[], 23, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-24', 'Can I change my status inside the UAE after finding a job?', 'Any in-country status change is subject to applicable UAE immigration and employment rules and approval by the relevant authority.', 'NEW_VISA', ARRAY['change', 'status', 'inside', 'uae']::text[], 24, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-25', 'Is UAE visa approval guaranteed?', 'No. The final visa decision is made by the relevant UAE authority.', 'NEW_VISA', ARRAY['uae', 'visa', 'approval', 'guaranteed']::text[], 25, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-26', 'What happens after my visa is approved?', 'The issued visa document is made available through the available TripNexio customer communication or account channel.', 'NEW_VISA', ARRAY['happens', 'visa', 'approved', 'issued']::text[], 26, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-27', 'How can I track my application?', 'Use Track Status to view the available booking, payment, document and visa updates for your application.', 'NEW_VISA', ARRAY['track', 'application', 'use', 'status']::text[], 27, true, true, CURRENT_TIMESTAMP),
  ('faq-new-visa-28', 'Can I cancel and request a refund?', 'Refund eligibility depends on the stage of your application and the applicable TripNexio refund terms.', 'NEW_VISA', ARRAY['cancel', 'refund', 'eligibility', 'depends']::text[], 28, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-1', 'What is UAE Visa Change?', 'Visa Change is a service for eligible travellers in the UAE who need an available exit-and-new-visa arrangement through Airport-to-Airport or Border Exit.', 'VISA_CHANGE', ARRAY['uae', 'visa', 'change', 'service']::text[], 1, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-2', 'Can I apply for Visa Change from India?', 'No. Visa Change is an in-UAE service. You need to be currently in the UAE to use this service.', 'VISA_CHANGE', ARRAY['apply', 'visa', 'change', 'india']::text[], 2, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-3', 'Can I apply if I am outside the UAE?', 'No. Customers outside the UAE should use the relevant New Visa service.', 'VISA_CHANGE', ARRAY['apply', 'outside', 'uae', 'customers']::text[], 3, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-4', 'Who can apply for Visa Change?', 'Eligible UAE tourist visa holders and eligible holders of a cancelled UAE residence visa may apply, subject to applicable immigration requirements, availability and the final decision of the relevant authority.', 'VISA_CHANGE', ARRAY['apply', 'visa', 'change', 'eligible']::text[], 4, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-5', 'What Visa Change options are available?', 'TripNexio supports two methods: Airport-to-Airport (A2A) and Border Exit.', 'VISA_CHANGE', ARRAY['visa', 'change', 'options', 'available']::text[], 5, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-6', 'What is Airport-to-Airport Visa Change?', 'A2A is an exit-by-air arrangement. TripNexio confirms the available airports, airline, flight, date and time before you select a package.', 'VISA_CHANGE', ARRAY['airport-to-airport', 'visa', 'change', 'exit-by-air']::text[], 6, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-7', 'What is Border Exit Visa Change?', 'Border Exit is a land-border arrangement. TripNexio confirms the border, pickup details, reporting time and travel details before you select a package.', 'VISA_CHANGE', ARRAY['border', 'exit', 'visa', 'change']::text[], 7, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-8', 'Can I choose my own airport or border?', 'No. Customers do not manually enter airport names, airport codes or border names. You will see the confirmed options available through TripNexio.', 'VISA_CHANGE', ARRAY['choose', 'own', 'airport', 'border']::text[], 8, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-9', 'Can I choose my pickup location or pickup person?', 'No. For Border Exit, pickup and operational details are confirmed by TripNexio and shown to you after availability is confirmed.', 'VISA_CHANGE', ARRAY['choose', 'pickup', 'location', 'person']::text[], 9, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-10', 'What information do I need to start?', 'You will need your full name, mobile number, email address, passport number, visa expiry date and nationality. Additional passenger details can be added where applicable.', 'VISA_CHANGE', ARRAY['information', 'start', 'full', 'name']::text[], 10, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-11', 'Does nationality affect the price?', 'Yes. Visa Change rates are configured nationality-wise and can also vary by method, package, passenger type, passenger count and applicable charges.', 'VISA_CHANGE', ARRAY['nationality', 'affect', 'price', 'visa']::text[], 11, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-12', 'When will I see the final price?', 'The final price is shown after availability is confirmed and you select a confirmed date, time and package.', 'VISA_CHANGE', ARRAY['see', 'final', 'price', 'shown']::text[], 12, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-13', 'When do I pay?', 'Payment is made after the confirmed package, final price and applicable terms are shown.', 'VISA_CHANGE', ARRAY['pay', 'payment', 'made', 'confirmed']::text[], 13, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-14', 'When will I receive my Booking ID?', 'Your Booking ID is generated after successful payment.', 'VISA_CHANGE', ARRAY['receive', 'booking', 'generated', 'successful']::text[], 14, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-15', 'When do I upload documents?', 'Actual document upload takes place after successful payment. The document checklist can vary by nationality and application.', 'VISA_CHANGE', ARRAY['upload', 'documents', 'actual', 'document']::text[], 15, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-16', 'Can my existing documents be reused?', 'Eligible valid documents already stored in your TripNexio customer record may be reused where applicable; the system can still request new documents when required.', 'VISA_CHANGE', ARRAY['existing', 'documents', 'reused', 'eligible']::text[], 16, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-17', 'Do I need to upload my exit proof?', 'No. Customers do not upload exit proof. Our TripNexio experts record Exit Completed in the booking.', 'VISA_CHANGE', ARRAY['upload', 'exit', 'proof', 'customers']::text[], 17, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-18', 'What happens after Exit Completed?', 'New Visa Processing starts. The customer/passenger information already collected can be reused, and additional documents may be requested if required.', 'VISA_CHANGE', ARRAY['happens', 'exit', 'completed', 'new']::text[], 18, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-19', 'How will I receive my confirmed A2A or Border details?', 'The confirmed package shows the operational details relevant to your selected method, including the applicable airport/flight or border/pickup information.', 'VISA_CHANGE', ARRAY['receive', 'confirmed', 'border', 'details']::text[], 19, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-20', 'Does Visa Change guarantee the new visa?', 'No. Visa approval is subject to the relevant authority, and TripNexio does not guarantee approval.', 'VISA_CHANGE', ARRAY['visa', 'change', 'guarantee', 'new']::text[], 20, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-21', 'Can a tourist visa holder apply for Visa Change?', 'Eligible tourist visa holders who are currently in the UAE may apply, subject to applicable immigration requirements and confirmed availability.', 'VISA_CHANGE', ARRAY['tourist', 'visa', 'holder', 'apply']::text[], 21, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-22', 'Can a cancelled residence visa holder apply for Visa Change?', 'Eligible holders of a cancelled UAE residence visa who are currently in the UAE may apply, subject to applicable immigration requirements and confirmed availability.', 'VISA_CHANGE', ARRAY['cancelled', 'residence', 'visa', 'holder']::text[], 22, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-23', 'Can I add another passenger?', 'Yes. The Visa Change journey supports multiple passengers, with passenger-specific details including nationality and Adult/Child classification.', 'VISA_CHANGE', ARRAY['add', 'another', 'passenger', 'visa']::text[], 23, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-24', 'What happens if additional documents are requested?', 'You will be notified and can upload the requested documents through the available secure document-upload process.', 'VISA_CHANGE', ARRAY['happens', 'additional', 'documents', 'notified']::text[], 24, true, true, CURRENT_TIMESTAMP),
  ('faq-visa-change-25', 'How long does Visa Change take?', 'Timing depends on availability, the selected package, operational arrangements and subsequent visa processing. TripNexio should display only the timeframe configured and confirmed for the selected service/package.', 'VISA_CHANGE', ARRAY['long', 'visa', 'change', 'take']::text[], 25, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-1', 'What is OTB (OK to Board)?', 'OTB is an airline clearance/update associated with the passenger''s flight booking or ticket. It is arranged before travel through the applicable airline process.', 'OTB', ARRAY['otb', 'ok', 'board']::text[], 1, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-2', 'What is an ECR passport?', 'ECR means “Emigration Check Required”. If “Emigration Check Required” is printed/endorsed on the Indian passport, it is an ECR passport.', 'OTB', ARRAY['ecr', 'passport']::text[], 2, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-3', 'Where can I find the ECR remark?', 'Check the passport''s last page or endorsement area for the words “Emigration Check Required”. Passport layouts can vary.', 'OTB', ARRAY['where', 'find', 'ecr', 'remark']::text[], 3, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-4', 'What if “Emigration Check Required” is not printed on my passport?', 'For this service, the passport is treated as Non-ECR / ECNR. OTB may not be required, but an ECNR / Non-ECR traveller can still request OTB if they want the airline clearance arranged and the applicable process supports it.', 'OTB', ARRAY['emigration', 'check', 'required', 'printed']::text[], 4, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-5', 'Is OTB mandatory for ECR passport holders?', 'For TripNexio''s customer guidance, Indian ECR passport holders travelling with an applicable eVisa should arrange OTB before travel.', 'OTB', ARRAY['otb', 'mandatory', 'ecr', 'passport']::text[], 5, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-6', 'Can an ECNR / Non-ECR passport holder request OTB?', 'Yes. OTB may not be required for an ECNR / Non-ECR traveller, but TripNexio can process it as an optional service where the applicable airline process supports it.', 'OTB', ARRAY['ecnr', 'non-ecr', 'passport', 'holder']::text[], 6, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-7', 'Can I apply for OTB from India?', 'Yes. TripNexio processes OTB updates for passengers departing from India.', 'OTB', ARRAY['apply', 'otb', 'india']::text[], 7, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-8', 'Can TripNexio update OTB if I am travelling from another country?', 'No. If an Indian traveller is departing from another country, TripNexio cannot update OTB through this service, even when the airline is India- or Gulf-based.', 'OTB', ARRAY['tripnexio', 'update', 'otb', 'travelling']::text[], 8, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-9', 'Which airlines can TripNexio process OTB with?', 'TripNexio can coordinate OTB updates with supported India- and Gulf-based airlines where the applicable airline process is available.', 'OTB', ARRAY['which', 'airlines', 'tripnexio', 'process']::text[], 9, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-10', 'Do I need to upload separate OTB documents?', 'No separate “OTB document” is issued. OTB is an update/clearance associated with the flight booking or ticket. TripNexio may still require passenger and travel information to process the update.', 'OTB', ARRAY['need', 'upload', 'separate', 'otb']::text[], 10, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-11', 'What information do I need?', 'Full name, passport number, mobile number, email address, destination country, airline and travel date.', 'OTB', ARRAY['information', 'need']::text[], 11, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-12', 'Do I need to enter my nationality?', 'No. No separate nationality field is required in the customer form. You need your full name, passport number, mobile number, email address, destination country, airline and travel date.', 'OTB', ARRAY['need', 'enter', 'nationality']::text[], 12, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-13', 'How will I know if my OTB has been updated?', 'TripNexio will provide the available status/update confirmation. You can also contact the airline''s customer support to confirm the OTB status, and airline check-in staff can check the airline system at the time of travel.', 'OTB', ARRAY['know', 'otb', 'has', 'been']::text[], 13, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-14', 'Can airline check-in staff see the OTB?', 'Where the airline has updated the OTB in its system, the airline''s check-in staff can check the status through the airline system.', 'OTB', ARRAY['airline', 'check-in', 'staff', 'see']::text[], 14, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-15', 'Can I contact the airline directly to confirm OTB?', 'Yes. After the OTB update, you may contact the airline''s customer support to confirm the status.', 'OTB', ARRAY['contact', 'airline', 'directly', 'confirm']::text[], 15, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-16', 'Can I get OTB at the airport?', 'OTB should be arranged before travel. Do not rely on obtaining the first OTB update at the airport.', 'OTB', ARRAY['get', 'otb', 'airport']::text[], 16, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-17', 'How early should I apply?', 'Airline timelines differ. Apply as early as possible before travel. Normal and Urgent processing availability depends on the selected airline and travel date.', 'OTB', ARRAY['early', 'should', 'apply']::text[], 17, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-18', 'What are Normal and Urgent processing?', 'Normal is standard processing when available. Urgent is a faster processing option when available for the selected airline and travel timing.', 'OTB', ARRAY['normal', 'and', 'urgent', 'processing']::text[], 18, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-19', 'Is the visa limited to a UAE visa?', 'No. TripNexio''s OTB service is not limited to UAE travel. The relevant destination visa should be valid for the destination and applicable to the passenger''s journey.', 'OTB', ARRAY['visa', 'limited', 'uae', 'visa']::text[], 19, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-20', 'Does OTB guarantee boarding?', 'No. TripNexio is the OTB service provider. Final boarding decisions remain with the airline.', 'OTB', ARRAY['otb', 'guarantee', 'boarding']::text[], 20, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-21', 'Does OTB guarantee immigration clearance?', 'No. Immigration and entry decisions remain with the relevant authorities.', 'OTB', ARRAY['otb', 'guarantee', 'immigration', 'clearance']::text[], 21, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-22', 'What happens if my OTB is not showing at check-in?', 'Ask the airline check-in staff to check the airline system and contact the airline''s customer support. You can also contact TripNexio support for assistance.', 'OTB', ARRAY['happens', 'otb', 'showing', 'check-in']::text[], 22, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-23', 'Can I cancel my OTB application?', 'Yes, subject to the stage of processing and the applicable refund rules.', 'OTB', ARRAY['cancel', 'otb', 'application']::text[], 23, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-24', 'What happens if I cancel before document validation?', 'Gateway charges are non-refundable and the eligible balance is processed according to the configured refund policy.', 'OTB', ARRAY['happens', 'cancel', 'document', 'validation']::text[], 24, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-25', 'What happens after document validation?', 'The applicable ₹250 service charge plus gateway charges are deducted from the eligible refund under the current OTB rules.', 'OTB', ARRAY['happens', 'document', 'validation']::text[], 25, true, true, CURRENT_TIMESTAMP),
  ('faq-otb-26', 'Is there a refund after airline processing?', 'No, under the current OTB business rules.', 'OTB', ARRAY['refund', 'airline', 'processing']::text[], 26, true, true, CURRENT_TIMESTAMP)
